import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('por-su-llaga-fuimos-curados', 'A',
 [dict(t=1983, e=2072, titulo='Llénate de amor para ser sano', txt='¿Estás lleno de amor, o todo circula alrededor tuyo y tu vida tiene que circular alrededor de Dios? Está serio esto, hermano, porque dice que si das tu cuerpo a quemar y diste toda tu vida, pero no tuviste amor, de balde. Entonces, el ingrediente esta mañana para que usted sea sano: que usted mismo se llene de amor y ame a los demás. Hay gente que no sana porque odia, y ese odio le trae enfermedad a su cuerpo, a su alma. Hoy el Señor viene a quitar todo odio que puedas tener contra alguien. […] Cuando la salida es que perdones, te arrepientas, te humilles y el Señor te exalte y estés lleno de amor. Cuando uno está lleno de amor, hermano, todo lo soporta, todo lo espera.'),
  dict(t=2492, e=2582, titulo='Morir al pecado y vivir a la justicia', txt='Primera de Pedro 2:24: «Y él mismo llevó nuestros pecados en su cuerpo sobre la cruz, a fin de que muramos al pecado». ¿Qué tiene que hacer efecto lo que hizo el Señor en la cruz? Que nosotros muramos al pecado que tanto le gusta y vivamos a la justicia. ¿Cuál es la justicia? Que lo que no quiero para mí no lo hago para otros. ¿Cuántos quieren ser justos? Por eso, tratémonos bien como ovejas, como padres, como esposos: que yo no quiera para mis hijos lo que no quiero para mí.'),
  dict(t=3511, e=3572, titulo='Tira el manto viejo', txt='Marcos 10:49: «Y Jesús se detuvo y dijo: Llamadle. Y llamaron al ciego, diciéndole: Anímate, levántate, que te llama». Hoy le vengo a decir: anímese, Cristo lo está llamando. «Y arrojando su manto». ¿Qué manto? […] En la enfermedad. Hoy muchos van a tener que tirar el manto viejo donde aceptaron enfermedades, donde aceptaron maldiciones que tal vez venían de su familia. Pero hoy se rompe: tira el manto. «¿Qué deseas que haga por ti?». Hoy el Señor Jesús agarra mi boca para decirte: ¿qué quieres que haga el Señor por ti?')],
 [dict(t=532, txt='A veces hay enfermedades por espíritus inmundos, hermano. Hay enfermedad por pecado.'),
  dict(t=3064, txt='Cuando se recuerda quién es su Dios y qué es lo que puede hacer con usted, no le importa lo que está viviendo.'),
  dict(t=4507, txt='Hoy esa carne que era muerte nos dio vida a usted y a mí.')],
 ['Si el odio y la falta de perdón enferman, ¿a quién necesitas perdonar hoy para llenarte del amor de Dios?',
  'Cristo llevó nuestros pecados para que vivamos a la justicia: ¿cómo tratas a los demás, como quisieras ser tratado?',
  'El ciego tiró su manto para ir a Jesús: ¿qué manto viejo necesitas tirar esta semana, y qué le pedirás al Señor?'],
 inicio=1162)
